package fetvisuals.animation;
public final class Animation {private float value,target;private final long duration;private Easing easing;private long last=System.currentTimeMillis();public Animation(float initial,long duration,Easing easing){value=target=initial;this.duration=duration;this.easing=easing;}public void target(float t){target=t;}public void easing(Easing e){easing=e;}public float update(){long now=System.currentTimeMillis();float dt=Math.min(1f,(now-last)/(float)duration);last=now;value+=(target-value)*easing.apply(dt);return value;}public float value(){return value;}}
